def section(lang='de',base=''):
 label,title,intro,choices,items,more,choose,description,note,idea,location,route,caption=COPY[lang]
 buttons=''.join(f'<button type="button" data-presence-choice="{key}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span>{e(name)}</button>' for i,(key,name) in enumerate(zip(['website','social','local'],choices)))
 cards=''.join(f'<article class="presence-service" data-presence-card="{key}"><p class="presence-service-kicker">0{i+1} / {e(item[0])}</p><h3>{e(item[1])}</h3><p>{e(item[2])}</p><small>{e(item[3])}</small><div><a href="{base}{item[4]}">{e(item[0])} ↗</a><a class="presence-enquire" href="{base}kontakt.html?thema=marketing&amp;leistung={quote(item[0])}#projektanfrage">{e(item[5])} ↗</a></div></article>' for i,(key,item) in enumerate(zip(['website','social','local'],items)))
 return f'''<section class="presence-section" id="digitaler-auftritt" data-boosty-section="website" data-presence="website"><div class="shell"><div class="presence-heading"><div><p class="v-kicker">{label}</p><h2>{title}</h2></div><p>{e(intro)}</p></div>
 <div class="presence-universe" data-boosty-scene role="img" aria-label="{e(description)}"><canvas class="presence-particles" aria-hidden="true"></canvas><div class="presence-horizon" aria-hidden="true"></div><div class="presence-orbit presence-orbit-one" aria-hidden="true"></div><div class="presence-orbit presence-orbit-two" aria-hidden="true"></div>
 <div class="presence-object presence-site" aria-hidden="true"><div class="presence-browser-bar"><i></i><i></i><i></i><span>tafolli.net</span></div><div class="presence-site-content"><small>TAFOLLI &amp; CO.</small><strong>{idea}</strong><span></span><b>Design. Development.</b></div></div>
 <div class="presence-object presence-social" aria-hidden="true"><div class="presence-phone-speaker"></div><small>TAFOLLI &amp; CO.</small><strong>Be<br>seen.</strong><div class="presence-reel-lines"><i></i><i></i><i></i><i></i></div><span>CONTENT / REELS / SOCIAL</span></div>
 <div class="presence-object presence-local" aria-hidden="true"><div class="presence-map"><i></i><i></i><i></i><span><svg viewBox="0 0 30 38" aria-hidden="true" focusable="false"><path d="M15 1C7.3 1 1 7 1 14.5 1 24 15 37 15 37s14-13 14-22.5C29 7 22.7 1 15 1Z" fill="currentColor"/><circle cx="15" cy="14" r="5" fill="white"/></svg></span></div><div><strong>{e(location)}</strong><small>{e(route)} <span>↗</span></small></div></div>
 <div class="presence-boosty" aria-hidden="true"><div><img src="{base}assets/work/boosty.webp" width="1200" height="1200" alt="" decoding="async"></div><span>BOOSTY</span></div><span class="presence-scene-label" aria-hidden="true">{caption}</span><span class="presence-scene-note" aria-hidden="true">{e(note)}</span></div>
 <div class="presence-controls" role="group" aria-label="{e(choose)}">{buttons}</div><div class="presence-services">{cards}</div></div></section>'''

def local_listings():
 return '''<section class="local-listings" id="lokale-eintraege" data-boosty-section="local"><div class="shell"><div class="local-heading"><div><p class="v-kicker">LOKALE EINTRÄGE &amp; UNTERNEHMENSPROFILE</p><h2>Ihr Unternehmen.<br>Auf der richtigen Karte.</h2></div><p>Wer in Ihrer Nähe nach einer Leistung sucht, sollte aktuelle und stimmige Angaben finden. Wir richten Profile ein, überarbeiten vorhandene Einträge und halten die vereinbarten Angaben aktuell.</p></div><div class="local-platforms"><article><span>01 / GOOGLE</span><h3>Google-Unternehmensprofil</h3><p>Kategorien, Leistungsbeschreibung, Kontaktdaten, Öffnungszeiten und Bilder für die Darstellung in Google Suche und Maps.</p></article><article><span>02 / APPLE</span><h3>Apple Maps</h3><p>Unternehmens- und Standortinformationen über Apple Business für die Darstellung in Apple Maps und weiteren unterstützten Apple-Diensten.</p></article><article><span>03 / BING &amp; VERZEICHNISSE</span><h3>Bing Places &amp; Brancheneinträge</h3><p>Relevante Karten- und Branchenprofile auswählen, einheitliche Angaben pflegen und doppelte oder veraltete Einträge prüfen.</p></article></div><div class="local-delivery"><div><h3>Ein stimmiger Auftritt. Auch im Detail.</h3><ul><li>Name, Adresse und Telefonnummer abgleichen</li><li>Öffnungszeiten, Feiertage und Leistungsgebiete pflegen</li><li>Website, Bilder und relevante Leistungen ergänzen</li><li>Zugänge, Freigaben und laufende Pflege klären</li></ul></div><div><p>Profile bleiben Ihrem Unternehmen zugeordnet. Bestätigungen durch die Plattformen begleiten wir mit Ihnen; Verfügbarkeit und Anforderungen richten sich nach Standort und Anbieter.</p><a class="btn btn-1" href="kontakt.html?thema=marketing&amp;leistung=Lokale%20Eintr%C3%A4ge#projektanfrage">Lokale Einträge besprechen ↗</a></div></div></div></section>'''
